head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자

// 화면 리사이징

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00400_02.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 결산일자 조회
    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ConnObjDpndCom_OnLoadError
 * @description dts_ConnObjDpndCom 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ConnObjDpndCom_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ConnObjDpndCom);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00400_02.dts_ConnObjDpndCom_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ConnObjDpndCom_OnLoadCompleted
 * @description dts_ConnObjDpndCom 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ConnObjDpndCom_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ConnObjDpndCom.errorMsg) {
            await $c.win.alert(dts_ConnObjDpndCom.errorMsg);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00400_02.dts_ConnObjDpndCom_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_ConnObjDpndCom_OnToolTipText
 * @description grd Conn Obj Dpnd Com On Tool Tip Text 처리
 * @param {Number} row 행 인덱스
 * @param {*} col col
 * @param {*} id id
 * @returns {void}
 * @hidden N
 */
scwin.grd_ConnObjDpndCom_OnToolTipText = function(row, col, id) {
    try {
        if (id === "CONN_RSN_CD") {
            return $c.stf.getConnRsnCdNm1(dts_ConnObjDpndCom.getCellData(row, "CONN_RSN_CD"));
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00400_02.grd_ConnObjDpndCom_OnToolTipText" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 연결대상종속회사 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ConnObjDpndCom",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ConnObjDpndCom=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ConnObjDpndCom.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.
    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();
    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDownload = async function() {
    if (dts_ConnObjDpndCom.getRowCount() <= 0) {
        await $c.win.alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ConnObjDpndCom, {fileName: "연결대상종속회사", type: "8"});
};
